{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_Zepto_Fact_Items_New AS WITH Sponsored_Display AS ( SELECT CAST(Atc AS INT64) AS Atc, CAST(Cpm AS FLOAT64) AS Cpm, CAST(Ctr AS FLOAT64) AS Ctr, PARSE_DATE(\'%Y-%m-%d\', Date) AS Date, CAST(Roas AS FLOAT64) AS Roas, CAST(Spend AS FLOAT64) AS Spend, CAST(Clicks AS INT64) AS Clicks, CAST(Orders AS INT64) AS Orders, CAST(BrandID AS STRING) AS BrandID, CAST(Revenue AS FLOAT64) AS Revenue, COALESCE(fsm.category,sd.Category) AS Category, CAST(BrandName AS STRING) AS BrandName, CAST(ProductID AS STRING) AS ProductID, CAST(Same_skus AS STRING) AS Same_skus, CAST(Other_skus AS STRING) AS Other_skus, CAST(Campaign_id AS STRING) AS Campaign_id, CAST(Impressions AS INT64) AS Impressions, CAST(ProductName AS STRING) AS ProductName, CAST(Campaign_name AS STRING) AS Campaign_name, COALESCE(km.collection , fsm.collection) AS Collection, \'Display\' AS Type FROM `MapleMonk.zept_zouk_db_sponsored_display` sd LEFT JOIN ( SELECT * FROM maplemonk.final_sku_master QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(Channel_Product_Id) ORDER BY IFNULL(collection, \'\') DESC) = 1 ) fsm ON LOWER(fsm.Channel_Product_Id) = LOWER(sd.ProductID) LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(sd.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') ) , Sponsored_Products AS ( SELECT CAST(Atc AS INT64) AS Atc, CAST(Cpm AS FLOAT64) AS Cpm, CAST(Ctr AS FLOAT64) AS Ctr, PARSE_DATE(\'%Y-%m-%d\', Date) AS Date, CAST(Roas AS FLOAT64) AS Roas, CAST(Spend AS FLOAT64) AS Spend, CAST(Clicks AS INT64) AS Clicks, CAST(Orders AS INT64) AS Orders, CAST(BrandID AS STRING) AS BrandID, CAST(Revenue AS FLOAT64) AS Revenue, coalesce(fsm.category,sp.Category) AS Category, CAST(BrandName AS STRING) AS BrandName, CAST(ProductID AS STRING) AS ProductID, CAST(Same_skus AS STRING) AS Same_skus, CAST(Other_skus AS STRING) AS Other_skus, CAST(Campaign_id AS STRING) AS Campaign_id, CAST(Impressions AS INT64) AS Impressions, CAST(ProductName AS STRING) AS ProductName, CAST(Campaign_name AS STRING) AS Campaign_name, COALESCE(km.collection, fsm.collection) AS Collection, \'Product\' AS Type FROM `MapleMonk.zept_zouk_db_sponsored_products` sp LEFT JOIN ( SELECT * FROM maplemonk.final_sku_master QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(Channel_Product_Id) ORDER BY IFNULL(collection, \'\') DESC) = 1 ) fsm ON LOWER(fsm.Channel_Product_Id) = LOWER(sp.ProductID) LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(sp.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') ) , Zepto_Ads AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', \'2025-01-15\') AS Date, SAFE_CAST(REPLACE(Spend, \',\', \'\') AS FLOAT64) AS Spend, SAFE_CAST(REPLACE(Roas, \',\', \'\') AS FLOAT64) AS Roas, SAFE_CAST(REPLACE(Ctr, \',\', \'\') AS FLOAT64) AS Ctr, SAFE_CAST(REPLACE(Cpc, \',\', \'\') AS FLOAT64) AS Cpc, SAFE_CAST(REPLACE(Atc, \',\', \'\') AS INT64) AS Atc, SAFE_CAST(REPLACE(Clicks, \',\', \'\') AS INT64) AS Clicks, SAFE_CAST(REPLACE(Orders, \',\', \'\') AS INT64) AS Orders, BrandID, SAFE_CAST(REPLACE(Revenue, \',\', \'\') AS FLOAT64) AS Revenue, BrandName, ProductID, Campaign_id, SAFE_CAST(REPLACE(Impressions, \',\', \'\') AS INT64) AS Impressions, ProductName, Campaign_name, fsm.category AS Category, COALESCE(km.collection, fsm.collection) AS Collection, \'Zepto\' AS Type FROM MapleMonk.zouk_db_Zepto_Ads za LEFT JOIN ( SELECT * FROM maplemonk.final_sku_master QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(Channel_Product_Id) ORDER BY IFNULL(collection, \'\') DESC) = 1 ) fsm ON LOWER(fsm.Channel_Product_Id) = LOWER(za.ProductID) LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(za.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') ) SELECT Atc, NULL AS Cpm, Ctr, Date, Roas, Spend, Clicks, Orders, BrandID, Revenue, Category, collection, BrandName, ProductID, NULL AS Same_skus, NULL AS Other_skus, Campaign_id, Impressions, ProductName, Campaign_name, Type FROM Zepto_Ads UNION ALL SELECT Atc, Cpm, Ctr, Date, Roas, Spend, Clicks, Orders, BrandID, Revenue, Category, collection, BrandName, ProductID, Same_skus, Other_skus, Campaign_id, Impressions, ProductName, Campaign_name, Type FROM Sponsored_Display UNION ALL SELECT Atc, Cpm, Ctr, Date, Roas, Spend, Clicks, Orders, BrandID, Revenue, Category, collection, BrandName, ProductID, Same_skus, Other_skus, Campaign_id, Impressions, ProductName, Campaign_name, Type FROM Sponsored_Products;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            